// slide-01.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: '2024 JavaScript Rising Stars: The Year\'s Hottest Projects by GitHub Stars'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative element
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.5,
    fill: { color: theme.accent }
  });

  slide.addText(slideConfig.title, {
    x: 0.5, y: 1.8, w: 9, h: 1.5,
    fontSize: 40, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center",
    margin: 0
  });

  slide.addText("9th Edition • Analyzing GitHub stars added in 2024 from Best of JS", {
    x: 1, y: 3.5, w: 8, h: 0.8,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

