};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.4, w: 0.15, h: 0.6,
    fill: { color: theme.accent }
  });
  slide.addText(slideConfig.title, {
    x: 0.8, y: 0.4, w: 8.5, h: 0.6,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true, valign: "middle"
  });

  // Chart
  const chartData = [
    {
      name: "Stars Added (in thousands)",
      labels: ["shadcn/ui", "Excalidraw", "AFFiNE", "Bruno", "n8n", "htmx", "Tauri", "Supabase", "Flowise", "Payload"].reverse(),
      values: [38.0, 27.0, 19.6, 18.7, 17.0, 16.8, 15.9, 14.5, 14.5, 14.4].reverse()
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.2, w: 9, h: 4,
    barDir: "bar",
    showValue: true,
    showLegend: false,
    catAxisLabelColor: theme.secondary,
    catAxisLabelFontFace: "Arial",
    catAxisLabelFontSize: 12,
    valAxisLabelColor: theme.secondary,
    valAxisLabelFontFace: "Arial",
    valAxisLabelFontSize: 12,
    chartColors: [theme.accent],
    valGridLine: { color: theme.light, style: "solid" }
  });

  // Badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

